  int fds[2];
  if (pipe(fds) != 0) {
    r.spawn_failed = true;
    return r;
  }

  pid_t pid = fork();
  if (pid < 0) {
    close(fds[0]);
    close(fds[1]);
    r.spawn_failed = true;
    return r;
