.section .text
.globl _start
_start:
    li      ra, 0x00100000
    li      sp, 0x00200000
    li      gp, 0x00300000
    li      tp, 0x00400000
    li      fp, 0x00500000           // x8

    slti   x0, x0,  0x5A0                 // QEMU1 drains, exits

    slti   x0, x0,  0x5A1                 // vsim drains, exits 200

