        g_free(newp);
        return r;
    }
    case 18: /* lstat */
    {
        struct stat st;
        char *path = andesim_strdup_guest(a0);
        int r = lstat(path, &st);

        if (r == 0) {
            andesim_store_guest_stat(a1, &st);
        }
        g_free(path);
        return r;
    }
    case 19: /* stat */
    {
