static void andesim_htif_dispatch(uint64_t tohost)
{
    uint8_t raw[ANDESIM_MAGIC_MEM_WORDS * 8];
    uint64_t m[ANDESIM_MAGIC_MEM_WORDS];
    hwaddr magic = tohost & MAKE_64BIT_MASK(0, 48);
    int i;

    if (tohost >> 48) {
        qemu_log_mask(LOG_GUEST_ERROR,
                      "andes_ae350: htif unknown device %#x\n",
                      (unsigned)(tohost >> 56));
        return;
    }
    cpu_physical_memory_read(magic, raw, sizeof(raw));
    for (i = 0; i < ANDESIM_MAGIC_MEM_WORDS; i++) {
        m[i] = ldq_le_p(raw + 8 * i);
    }
    m[0] = andesim_htif_syscall(m);
    for (i = 0; i < ANDESIM_MAGIC_MEM_WORDS; i++) {
        stq_le_p(raw + 8 * i, m[i]);
