/* rv32 issues the tohost word as two 32-bit halves (0x10 low, 0x14 high). */
static uint64_t andesim_htif_partial;
static int andesim_htif_parts;

static void andesim_htif_half(uint64_t val, int shift)
{
    andesim_htif_partial |= val << shift;
    if (++andesim_htif_parts == 2) {
        andesim_htif_dispatch(andesim_htif_partial);
        andesim_htif_partial = 0;
        andesim_htif_parts = 0;
    }
}

/* SimControl write handler. Offset 0 is the exit command:
 *   value < 256          → raw exit code (used by vplat _exit()).
 *   0x01234567/68/71     → exit 0  (FINISHED / PASSED / SKIPPED)
 *   0x01234569/70        → exit 1  (FAILED / WARNING)
 * Offset 0x4 is HTIF putchar; 0x10/0x14 carry the HTIF syscall command. */
static void sim_ctrl_write(void *opaque, hwaddr offset,
                           uint64_t val, unsigned size)
{
    (void)opaque;
    switch (offset) {
    case 0x0:
    {
        int code;

        if (val < 256) {
            code = (int)(uint32_t)val;
        } else if (val == 0x01234567 || val == 0x01234568 ||
                   val == 0x01234571) {
            code = 0;
        } else if (val == 0x01234569 || val == 0x01234570) {
            code = 1;
        } else {
            return;
        }
        exit(code);
    }
    case ANDESIM_HTIF_PUTCHAR_OFFSET:
        putchar((int)val);
        return;
    case ANDESIM_HTIF_CMD_OFFSET:
        if (size == 8) {
            andesim_htif_dispatch(val);
        } else {
            andesim_htif_half(val, 0);
        }
        return;
    case ANDESIM_HTIF_CMD_HIGH_OFFSET:
        andesim_htif_half(val, 32);
        return;
    default:
        qemu_log_mask(LOG_GUEST_ERROR,
                      "andes_ae350: sim_ctrl spurious write at %#" PRIx64
                      ", size %u\n", (uint64_t)offset, size);
        return;
    }
}

static uint64_t sim_ctrl_read(void *opaque, hwaddr offset, unsigned size)
{
    (void)opaque; (void)offset; (void)size;
    return 0; /* the device is write-only, like the vsim SimControl */
}

static const MemoryRegionOps andesim_ctrl_ops = {
    .read = sim_ctrl_read,
    .write = sim_ctrl_write,
    .endianness = DEVICE_LITTLE_ENDIAN,
    .valid = { .min_access_size = 1, .max_access_size = 8 },
    .impl = { .min_access_size = 1, .max_access_size = 8 },
};

